window.POETRY_REGISTER("v5-extra-13-5-0-07c65f8f7575.js",{"poems":[[52224,2],[54573,2],[54628,2],[55398,2],[55581,2],[56817,2],[56819,2],[57623,2],[57766,2],[58526,2],[109549,7],[194740,7],[199110,7],[282128,7],[297987,7],[304094,7],[319517,7],[346974,9],[351001,9],[358940,9],[360984,9],[371067,10],[398237,13],[413226,8],[474409,8],[504524,8],[504606,8],[518168,8],[575420,8],[575422,8],[575423,8],[575734,8],[589108,8],[596186,8],[652443,5],[657805,5],[660776,5],[667668,5],[679445,5],[725696,5]],"pairs":[["彦伯于武后垂拱间为云间主簿","屡迁给事中",0],["有杨于陵贞元八年后曾任此职","其时已较后",1],["似巨川于朱泚乱时亦陷身贼中","至德宗收京",2],["或清越为贯休早年所用之法名","识此俟考详",3],["此经幢今在无锡市锡惠公园内","为八面刻石",4],["马淑之先君在江南为饶州副使","其前妻冯氏",5],["此书作者乐史为南唐入宋之人","又为江西人",6],["此首实五代后蜀周某所作的诗","既非少陵作",7],["又推测苏癿应为哥舒翰同时人","亦可备一说",8],["五祖于蕲州蕲水得传四祖心印","故言受心灯",9],["肃进拜于庙堂兮宜奉时之牲酒","鼓钟兮在宫",10],["仙荒佛怪驱喝雷电笔意窥渺茫","不若收所画",11],["又如锦苔封漫岘山千年堕泪碑","又如玉关客",12],["至今药炉丹鼎髣髴千仞之层崖","目亦不能尽",13],["不然安得有此瑞彩突兀来峥嵘","天公有妙手",14],["奈抱此蹇蹇兮若膏肓其不可针","横浦兮幽绝",15],["不忍我家与国同休三百十六年","阅历凡几世",16],["不知几十里到先生南山之上京","朝耕肆微勤",17],["为问竹枝芦叶若为写出秦青讴","四座皆感叹",18],["但见飞霞笑电摇光九道叠云锦","天河中断摧",19],["使我梦寐至今夜夜空与相往还","卢郎天台人",20],["惊起五百罗汉半夜拨剌冲天飞","一鬼乘白豕",21],["不忍我家与国同休三百十六年","阅历凡几世",22],["送入樊笼相过使我洒泪如醉醒","握手尘市中",23],["香炉紫烟缭绕五城十二昆仑丘","憩公无量阁",24],["龙曷能然兮乘气与时斯以体干","尺窟兮非渊",25],["秦城莽莽汉关磊磊吊古还思今","挥君贾生涕",26],["乘白日之馀光兮择芳渚而憩之","桂棹兮兰桨",27],["著书明道亦与治水拯世之功均","吾为孔子徒",28],["纺绩衣食使入庠序拜揖从先生","所学在大伦",29],["咄尔四方之士孰不争先而骏奔","王道有通塞",30],["独立瑶台百尺之上月色传其真","冥观六合间",31],["闻有金银宫阙五城十二之琼楼","我欲往从之",32],["俨如天王神武虎臣矫矫来千城","离宫富炎德",33],["故赐额纳伸曰卓礼克图巴图鲁","卓礼克图者",34],["须向石渠虎观挥毫驰骋帝王侧","否则穷深山",35],["讵乃色然怒曰咄尔措大何敢然","自吾居而所",36],["惟有升真洞天未及杖策穷厜㕒","朅来芝城中",37],["对菱花不语蹙双娥奈归期无准","薄醉浑难醒",38],["还听冰融春涧潺湲一水鸣轻涛","轻涛殊不恶",39],["得之往往在于寂寞荒凉之穷野","日落晚风凉",39]]});
